def extract_features_for_classification(trajectory_data):
    steps = trajectory_data['steps']
    plan = [s['data'] for s in steps if s['name'] == 'PlanControllerAgent']
    return {"user_intent": trajectory_data['intent'], "plan_note": plan[-1] if plan else "",
            "n_prior_steps": len(steps)}
features = extract_features_for_classification(trajectory)

# --- appended by TabAgent (not LLM-written): flatten nested dicts, as the CodeExtractor prompt asks ---
def _tabagent_flatten(obj, prefix=""):
    flat = {}
    for key, value in obj.items():
        if isinstance(value, dict):
            flat.update(_tabagent_flatten(value, f"{prefix}{key}_"))
        elif isinstance(value, float) and (value != value or value in (float("inf"), float("-inf"))):
            flat[f"{prefix}{key}"] = None
        else:
            flat[f"{prefix}{key}"] = value
    return flat


if isinstance(features, dict):
    features = _tabagent_flatten(features)


# --- appended by TabAgent (not LLM-written): the decision's context as text ---
def _tabagent_context_text(trajectory_data, limit=4000, skip=('score', 'eval', 'evaluation', 'reward', 'success', 'outcome')):
    parts = []
    for key, value in trajectory_data.items():
        if key != "steps" and key not in skip and isinstance(value, str) and value.strip():
            parts.append(value.strip())
    for step in trajectory_data.get("steps") or []:
        if not isinstance(step, dict) or step.get("name") == "system":
            continue
        for key in ("content", "text", "thoughts", "intent", "data"):
            value = step.get(key)
            if isinstance(value, str) and value.strip():
                parts.append(value.strip())
    text = "\n".join(parts)
    if len(text) <= limit:
        return text
    return text[: limit // 4] + "\n...\n" + text[-(limit - limit // 4) :]


if isinstance(features, dict):
    features['context_text'] = _tabagent_context_text(trajectory)

